mapper.select:
select recent.id,
       recent.conversation_id,
       recent.message_type,
       recent.content,
       recent.created_at
from (
    select id, conversation_id, message_type, content, created_at
    from ai_chat_memory
    where conversation_id = #{conversationId}
      and id > #{afterId}
    order by id desc
    limit #{limit}
) recent
order by recent.id asc

select id, conversation_id, message_type, content, created_at
from ai_chat_memory
where conversation_id = #{conversationId}
  and id > #{afterId}
order by id asc
limit #{limit}
